diff:
diff --git a/scripts/Dpkg/BuildProfiles.pm b/scripts/Dpkg/BuildProfiles.pm
index d6cbd3f..7f23113 100644
--- a/scripts/Dpkg/BuildProfiles.pm
+++ b/scripts/Dpkg/BuildProfiles.pm
@@ -80,6 +80,11 @@ sub set_build_profiles {
     my (@profiles) = @_;

     $cache_profiles = 1;
+    # This is called from dpkg-buildpackage.pl unconditionally. If no profile
+    # was passed from the command line, check the environment variable.
+    if (!@profiles && Dpkg::Build::Env::has('DEB_BUILD_PROFILES')) {
+        @profiles = split ' ', Dpkg::Build::Env::get('DEB_BUILD_PROFILES');
+    }
     @build_profiles = @profiles;
     run_vendor_hook('update-buildprofiles', \@build_profiles);
     Dpkg::Build::Env::set('DEB_BUILD_PROFILES', join ' ', @build_profiles);
diff --git a/scripts/t/Dpkg_BuildProfiles.t b/scripts/t/Dpkg_BuildProfiles.t
index 396c31b..bf4851b 100644
--- a/scripts/t/Dpkg_BuildProfiles.t
+++ b/scripts/t/Dpkg_BuildProfiles.t
@@ -16,7 +16,7 @@
 use strict;
 use warnings;

-use Test::More tests => 10;
+use Test::More tests => 11;

 BEGIN {
     use_ok('Dpkg::BuildProfiles', qw(parse_build_profiles
@@ -72,5 +72,16 @@ set_build_profiles(qw(!noudeb nocheck stage1));
 is_deeply([ get_build_profiles() ], [ qw(nocheck stage1) ],
     'get active build profiles explicitly set');

+{
+    local $ENV{DEB_BUILD_PROFILES} = 'cross nodoc profile.name';
+
+    # dpkg-buildpackage.pl calls set_build_profiles with an empty array by
+    # default (unless --build-profiles is used), ensure the env var is still
+    # parsed
+    set_build_profiles(qw());
+    is_deeply([ get_build_profiles() ], [ qw(noudeb cross nodoc profile.name) ],
+        'get active build profiles from environment');
+}
+

 1;
